import urllib.request
import urllib.error
import json
import ssl
import sys

def check_endpoint(url):
    """Check the health of an endpoint and return response details"""
    try:
        # For HTTPS connections, create unverified context for simplicity
        # In production, proper certificate verification should be used
        context = ssl.create_default_context()
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE

        # Make request with a timeout
        request = urllib.request.Request(url)
        response = urllib.request.urlopen(request, timeout=10, context=context)

        # Read response
        content = response.read().decode('utf-8')

        return {
            'status': 'success',
            'status_code': response.getcode(),
            'response_body': content,
            'headers': dict(response.headers),
            'url': url
        }
    except urllib.error.HTTPError as e:
        return {
            'status': 'error',
            'status_code': e.code,
            'error_message': str(e),
            'url': url
        }
    except urllib.error.URLError as e:
        return {
            'status': 'error',
            'error_message': str(e.reason) if hasattr(e, 'reason') else str(e),
            'url': url
        }
    except Exception as e:
        return {
            'status': 'error',
            'error_message': str(e),
            'url': url
        }

def analyze_response(result):
    """Analyze the response and report any warnings or issues"""
    print(f"\n--- Checking {result['url']} ---")

    if result['status'] == 'error':
        print(f"❌ ERROR: {result['error_message']}")
        return

    print(f"✅ SUCCESS: Status Code {result['status_code']}")

    # Check for common warning signs
    if result['status_code'] >= 500:
        print(f"⚠️  WARNING: Server error (5xx status code)")
    elif result['status_code'] >= 400:
        print(f"⚠️  WARNING: Client error (4xx status code)")

    # Display response body if it's JSON and not too long
    body = result.get('response_body', '')
    if body:
        try:
            # Try to parse as JSON
            json_data = json.loads(body)
            print("📄 Response (JSON):")
            print(json.dumps(json_data, indent=2))
        except json.JSONDecodeError:
            # Not JSON, display as plain text if not too long
            if len(body) <= 500:
                print(f"📄 Response:\n{body}")
            else:
                print(f"📄 Response (truncated):\n{body[:500]}...")

if __name__ == "__main__":
    # Endpoints to check
    endpoints = [
        "http://localhost:47301/checkConnectivity?variant=2",
        "https://httpstat.us/200"
    ]

    print("🔍 Checking endpoint health...")

    for endpoint in endpoints:
        result = check_endpoint(endpoint)
        analyze_response(result)

